-- Módulo 37 ControlCalidadProductoTerminado: inspecciones finales de las unidades producidas por una orden.
-- Spec: docs/specs/modulo37-control-calidad-producto-terminado-backend.md (§4).

CREATE TABLE "InspeccionesProductoTerminado" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Numero" character varying(20) NOT NULL,
    "OrdenProduccionId" integer NOT NULL,
    "FechaInspeccion" date NOT NULL,
    "CantidadInspeccionada" integer NOT NULL,
    "ToleranciaNoConformesPorcentaje" numeric(5,2) NOT NULL,
    "Inspector" character varying(100) NOT NULL,
    "Estado" character varying(10) NOT NULL,
    "CantidadNoConforme" integer,
    "FechaDictamen" timestamp with time zone,
    "Observaciones" character varying(500),
    "MotivoAnulacion" character varying(250),
    CONSTRAINT "PK_InspeccionesProductoTerminado" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_InspeccionesProductoTerminado_OrdenesProduccion_OrdenProduccionId"
        FOREIGN KEY ("OrdenProduccionId") REFERENCES "OrdenesProduccion" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_InspeccionesProductoTerminado_CantidadInspeccionada" CHECK ("CantidadInspeccionada" > 0),
    CONSTRAINT "CK_InspeccionesProductoTerminado_Tolerancia"
        CHECK ("ToleranciaNoConformesPorcentaje" BETWEEN 0 AND 100),
    CONSTRAINT "CK_InspeccionesProductoTerminado_CantidadNoConforme"
        CHECK ("CantidadNoConforme" IS NULL OR ("CantidadNoConforme" >= 0 AND "CantidadNoConforme" <= "CantidadInspeccionada")),
    CONSTRAINT "CK_InspeccionesProductoTerminado_Estado"
        CHECK ("Estado" IN ('Pendiente', 'Aprobada', 'Rechazada', 'Anulada'))
);

CREATE UNIQUE INDEX "IX_InspeccionesProductoTerminado_Numero" ON "InspeccionesProductoTerminado" ("Numero");
CREATE INDEX "IX_InspeccionesProductoTerminado_OrdenProduccionId" ON "InspeccionesProductoTerminado" ("OrdenProduccionId");
CREATE INDEX "IX_InspeccionesProductoTerminado_FechaInspeccion" ON "InspeccionesProductoTerminado" ("FechaInspeccion");
CREATE INDEX "IX_InspeccionesProductoTerminado_Estado" ON "InspeccionesProductoTerminado" ("Estado");
